<script>
document.addEventListener('DOMContentLoaded',()=>{
 const csrf=@json(csrf_token());
 async function send(url,data,method='POST') {
  const response=await fetch(url,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':csrf,...(data instanceof FormData ? {} : {'Content-Type':'application/json'})},body:data instanceof FormData ? data : JSON.stringify(data)});
  const result=await response.json();if(!response.ok)throw Error(Object.values(result.errors || {}).flat().join('\n') || result.message || 'تعذر الحفظ');return result;
 }
 document.addEventListener('invalid',event=>{let details=event.target.closest('details');while(details){details.open=true;details=details.parentElement.closest('details');}const pane=event.target.closest('.tab-pane');if(pane){const button=document.querySelector('[data-bs-target="#'+pane.id+'"]');if(button)bootstrap.Tab.getOrCreateInstance(button).show();}},true);
 function tierForm(form){const attribute=form?.elements.attribute_id,category=form?.elements.service_category_id;if(attribute&&category&&!attribute.dataset.bound){attribute.dataset.bound=1;const groups=[...attribute.querySelectorAll('optgroup')].map(g=>g.cloneNode(true));const refresh=()=>{const value=attribute.value;attribute.replaceChildren(new Option('بدون سمة',''));groups.filter(g=>g.dataset.category===category.value).forEach(g=>attribute.append(g.cloneNode(true)));attribute.value=[...attribute.options].some(o=>o.value===value)?value:'';};category.addEventListener('change',refresh);refresh();}const hours=form?.querySelector('[data-duration-hours]'),minutes=form?.querySelector('[data-duration-minutes]');if(hours&&minutes){const sync=()=>{form.elements.duration_minutes.value=Number(hours.value)*60+Number(minutes.value);form.elements.hours_per_visit.value=Number(form.elements.duration_minutes.value)/60;};hours.addEventListener('input',sync);minutes.addEventListener('input',sync);}const tier=form?.elements.package_tier_id;if(!tier||tier.dataset.bound)return;tier.dataset.bound='1';const months=form.elements.recurring_months,visits=form.elements.visits_count;function update(recalculate){const option=tier.selectedOptions[0],once=option.dataset.frequency==='one_off';months.min=once?0:1;months.readOnly=once;visits.readOnly=once;if(once){months.value=0;visits.value=1;}else{if(Number(months.value)<1)months.value=1;if(recalculate||!visits.value)visits.value=Math.round(Number(option.dataset.rate)*4*Number(months.value));}}tier.addEventListener('change',()=>update(true));months.addEventListener('input',()=>update(true));update(false);}
 document.querySelectorAll('form').forEach(tierForm);
 document.addEventListener('click',event=>{if(event.target.closest('[data-item-close]')&&!event.target.closest('.modal'))location.href=@json(route('admin.hourly-service-items.index'));});
 function bindForm(body){const form=body.querySelector('form');if(!form)return;tierForm(form);form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button:not([type="button"])');button.disabled=true;let errorBox=body.querySelector('.item-errors');if(!errorBox){errorBox=document.createElement('div');errorBox.className='alert alert-danger item-errors';body.prepend(errorBox);}errorBox.hidden=true;try{await send(form.action,new FormData(form));location.reload();}catch(error){errorBox.textContent=error.message;errorBox.hidden=false;errorBox.scrollIntoView({block:'nearest'});}finally{button.disabled=false;}});}
 document.addEventListener('click',event=>{const button=event.target.closest('[data-time-choice]');if(!button)return;const select=button.nextElementSibling,values=['off','all','dispatch'];select.value=values[(values.indexOf(select.value)+1)%3];button.classList.remove('btn-outline-secondary','btn-success','btn-warning');button.classList.add({off:'btn-outline-secondary',all:'btn-success',dispatch:'btn-warning'}[select.value]);button.setAttribute('aria-label',button.textContent+' — '+select.selectedOptions[0].text);const general=button.closest('form').elements.use_general_schedule;if(general)general.checked=false;});
 document.querySelectorAll('[data-item-form]').forEach(button=>button.addEventListener('click',async()=>{const body=document.getElementById('item-modal-body');body.textContent='جارٍ التحميل…';bootstrap.Modal.getOrCreateInstance(document.getElementById('item-modal')).show();try{const response=await fetch(button.dataset.itemForm,{headers:{'X-Requested-With':'XMLHttpRequest'}});if(!response.ok)throw Error('تعذر تحميل النموذج');body.innerHTML=await response.text();document.querySelector('#item-modal .modal-header h5').textContent=body.querySelector('form').elements._method?'تعديل الباقة':'إضافة باقة خدمة';bindForm(body);}catch(error){body.textContent=error.message;}}));
 function updatePublication(key,report){const badge=document.querySelector('[data-publication-key="'+key+'"]');if(!badge||!report)return;badge.classList.toggle('is-hidden',!report.visible);badge.dataset.websiteVisible=report.visible?'1':'0';badge.querySelector('[data-publication-label]').textContent=report.visible?'يظهر في الموقع':'لا يظهر في الموقع';badge.querySelector('i').className='fa '+(report.visible?'fa-eye':'fa-eye-slash');const tip=badge.querySelector('[role=tooltip]')||document.getElementById(key);tip.replaceChildren(...report.reasons.map(reason=>{const line=document.createElement('span');line.textContent=reason;return line;}));}
 document.querySelectorAll('[data-item-status]').forEach(input=>input.addEventListener('change',async()=>{input.disabled=true;try{const result=await send(input.dataset.itemStatus,{is_active:input.checked},'PUT');input.nextElementSibling.textContent=input.checked?'نشط':'متوقف';updatePublication('website-package-'+result.id,result.publication);updatePublication('website-category-'+result.category_id,result.category_publication);}catch(error){input.checked=!input.checked;const feedback=document.getElementById('item-feedback');feedback.className='alert alert-danger';feedback.textContent=error.message;}finally{input.disabled=false;}}));
 document.querySelectorAll('.item-quick-price').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await send(form.action,{total_price:form.elements.total_price.value},'PUT');location.reload();}catch(error){const box=document.getElementById('item-feedback');box.className='alert alert-danger';box.textContent=error.message;}finally{button.disabled=false;}}));
 function describe(values){return Object.entries(values).filter(([key])=>key!=='price_per_visit').map(([key,value])=>{
  if(key==='start_times')return value===null?'مواعيد التشغيل العامة':Object.entries(value).map(([time,access])=>time+' ('+(access==='all'?'الجميع':'التشغيل فقط')+')').join('، ') || 'بدون مواعيد';
  return ({total_price:'إجمالي الباقة',break_minutes:'الاستراحة',buffer_minutes:'الفاصل'}[key] || key)+': '+value+(key==='total_price'?' ر.س':' دقيقة');
 }).join(' — ');}
 document.querySelectorAll('.item-bulk-form').forEach(form=>{
  const result=form.parentElement.querySelector('.bulk-result'),save=form.parentElement.querySelector('.bulk-save');let token=null,version=0;
  function reset(){version++;token=null;save.hidden=true;result.replaceChildren();}
  form.addEventListener('input',reset);form.addEventListener('change',()=>{reset();const type=form.elements.type.value;form.querySelectorAll('[data-bulk-section]').forEach(section=>{section.hidden=section.dataset.bulkSection!==type;section.disabled=section.hidden;});});
  form.addEventListener('submit',async event=>{event.preventDefault();reset();const current=version,button=form.querySelector('[type="submit"]');button.disabled=true;result.textContent='جارٍ حساب المعاينة…';try{const data=await send(@json(route('admin.hourly-service-items.preview')),new FormData(form));if(current!==version)return;token=data.token;result.replaceChildren();data.rows.forEach(row=>{const panel=document.createElement('div');panel.className='border rounded p-2 mb-2';const heading=document.createElement('strong');heading.textContent=row.name;panel.append(heading);['before','after'].forEach(key=>{const line=document.createElement('p');line.className='small mb-1';line.textContent=(key==='before'?'قبل: ':'بعد: ')+describe(row[key]);panel.append(line);});result.append(panel);});save.hidden=false;}catch(error){if(current===version)result.textContent=error.message;}finally{button.disabled=false;}});
  save.addEventListener('click',async()=>{if(!token)return;save.disabled=true;try{await send(@json(route('admin.hourly-service-items.apply')),{token});location.reload();}catch(error){result.textContent=error.message;save.hidden=true;token=null;}finally{save.disabled=false;}});
 });
});
</script>
